'use strict';
// Setup orchestration only: all actual control execution stays in the existing modules.
let setupConversation=[],moduleResetting=false,agentApplication=null,setupListening=false;
function needsSetupReply(plan){
 return plan.status==='clarify'||plan.status==='ready'&&plan.mapping.output?.startsWith('mixxx.')&&!!djGuide&&!['pickup','done'].includes(djGuide.phase);
}
function moduleContext(){
 return {mapping:morphMapping,game:gameModuleObject?{profile:$('game-module').value,object_id:gameModuleObject}:null,
  controls:[...controlEntries.values()].map(e=>e.mapping),dj_setup:djGuide,dj_mappings:djState?.mappings||{}};
}
function rememberSetup(transcript,message){
 setupConversation.push({transcript:transcript.slice(0,1000),message:message.slice(0,1000)});
 setupConversation=setupConversation.slice(-8);
}
async function activateModulePlan(mapping,message){
 if(moduleResetting)throw Error('Module reset in progress.');
 const item=objects('top').find(o=>o.observation.object_id===mapping.object_id&&o.observation.tracking_state==='tracked');
 if(!running||studioDemo||!item||performance.timeOrigin+performance.now()-cameras.top.acceptedSample>250)throw Error('Show the object again, then repeat your command.');
 if(GAME_MODULES[mapping.module]){
  gameModuleOptions();$('game-module').value=mapping.module;$('game-object').value=mapping.object_id;
  if($('game-object').value!==mapping.object_id)throw Error('Object is no longer available.');
  $('keyboard-mode').value='game';
  await mapGameModule(true);
  $('command-status').textContent=message+' · '+GAME_MODULES[mapping.module].help+' Focus your game to use it. Keyboard output: '+$('keyboard-status').textContent;
  return;
 }
 if(mapping.output?.startsWith('mixxx.')){
  const action=mapping.setup_action||'map';
  if(action==='map'){
   await api('/api/dj/arm',{enabled:false});
   await activateDJPlan(mapping,message);
   djGuide={target:mapping.output,id:mapping.object_id,phase:'low'};
  }else{
   if(!djGuide||djGuide.id!==mapping.object_id||djGuide.target!==mapping.output)throw Error('First tell me which object controls this DJ fader.');
   const expected={calibrate_low:'low',calibrate_high:'high',enable:'enable'}[action];
   if(djGuide.phase!==expected)throw Error('Complete the current DJ setup step first: '+djGuide.phase+'.');
   // Use the very same calibration/enable routine as the manual setup buttons.
   await djGuideNext();
   if(djGuide.phase===expected)throw Error($('dj-guide-error').textContent||'DJ setup could not advance.');
  }
  if(djState)djGuideRender(djState);
  const instructions={low:'Move this object to its 0% end and say “save minimum”.',high:'Move it to its 100% end and say “save maximum”.',enable:'Travel calibrated. Say “enable DJ controls”.',pickup:'Move through the current Mixxx fader value to pick up control.',done:'Ready. Tell me which object to map next.'};
  $('command-status').textContent=instructions[djGuide.phase];return;
 }
 if(['slider_x','slider_y','cover_button'].includes(mapping.controller)){
  // Independent saved controls use the existing ActionGroup, including its watchdog.
  await removeDJSource(mapping.object_id);
  if(controlBusy)throw Error('A control is being activated. Try again shortly.');
  const number=++controlNumber;
  const target=controlsCatalog?.targets?.[mapping.output]?.label||mapping.output;
  const entry={mapping:{...mapping},source:`#${item.number} ${item.object_label}`,target,name:message};
  // Reassigning this input replaces its previous general mapping; other objects keep theirs.
  for(const [key,old] of controlEntries)if(old.mapping.object_id===mapping.object_id){
   if(old.token)await api('/api/controls/stop',{token:old.token});controlEntries.delete(key);
  }
  controlEntries.set(number,entry);renderControlEntries();
  await activateControlEntry(number);
  if(!entry.token)throw Error($('controls-status').textContent||'Mapping saved; output could not start.');
  $('command-status').textContent=message;return;
 }
 await activateMorph(mapping,message);
}
async function stopModuleOutputs(reason){
 await stopRealKeys(reason);
 await stopGeneralControls();
 await api('/api/dj/arm',{enabled:false});
}
async function resetModule(){
 if(moduleResetting)return;
 moduleResetting=true;setupListening=false;cancelVoice();$('module-reset').disabled=true;
 const resume=running;running=false;commandVersion++;commandRequest?.abort();
 for(const c of Object.values(cameras))clearTimeout(c.timer);
 try{
  await finishCommand(false);
  if(agentApplication)try{await agentApplication;}catch(_){}
  await stopModuleOutputs('Module reset');
  await Promise.all(Object.values(cameras).map(async c=>{if(c.inFlight)try{await c.inFlight;}catch(_){}}));
  await api('/api/module/reset',{});
  keyboardToken=null;actionToken=null;keyboardObject=null;actionRegion=null;
  morphMapping=null;morphPrevious=null;commandMotion.clear();setupConversation=[];
  controlEntries.clear();renderControlEntries();djGuide=null;djGuideError();
  gameModuleObject=null;flightAnchor=null;fixedGameAnchor=null;sessionStorage.removeItem('fixed-game-anchor');
  registeringRegion=false;regionStart=null;delete regionCanvas.dataset.region;regionCanvas.classList.remove('registering-region');
  canJoystickArmed=false;sessionStorage.removeItem('can-joystick-armed');
  flatInputs.clear();dismissedFlatInputs.clear();pairs.length=0;candidates.clear();pairNumber=0;
  for(const role of roles){cameras[role].result=null;cameras[role].acceptedSample=null;clearOverlay(role);}
  $('flat-tracks').replaceChildren();$('tracks').replaceChildren();$('command-transcript').textContent='';$('command-text').value='';
  renderMorph();draw();updateStudio();await djRefresh();
  $('command-status').textContent='Module reset. Move your objects briefly, then tell me what you want to control.';
  if(resume){running=true;previewLoop(generation);roles.filter(role=>cameras[role].stream&&!cameras[role].disabled).forEach(role=>pump(role,generation));}
 }catch(err){$('command-status').textContent='Reset did not complete: '+err.message+'. Outputs are stopped; retry reset.';}
 finally{moduleResetting=false;$('module-reset').disabled=false;$('command-talk').disabled=false;$('command-text-send').disabled=false;$('command-cancel').disabled=true;}
}
$('module-reset').addEventListener('click',()=>void resetModule());
